// ── Filters ──────────────────────────────────────────────────────────────────
export const CATEGORIES        = [...new Set(ROWS.map(r => r.category))].sort();
export const MARKETS           = [...new Set(ROWS.map(r => r.market))].sort();
// CATEGORY_MANAGERS is re-exported from the authoritative mapping file
// so the filter dropdown always reflects the live org chart
export { ALL_CATEGORY_MANAGERS as CATEGORY_MANAGERS } from '@/lib/category-managers';

// ── Aggregation helpers ──────────────────────────────────────────────────────
export function computeMetrics(rows: SpendRow[]): MetricsResult {
  if (rows.length === 0) {
    return {
      totalActualSpendEur: 0, totalAwardedSpendEur: 0, budgetUtilizationPct: 0,
      supplierCount: 0, contractStart: '—', contractEnd: '—', budgetRisk: '—',
      avgAdherencePct: 0, atRiskSuppliers: 0,
    };
  }
  const maxPerSup = new Map<string, { actual: number; awarded: number }>();
  for (const r of rows) {
    const cur = maxPerSup.get(r.supplier) ?? { actual: 0, awarded: 0 };
    maxPerSup.set(r.supplier, {
      actual:  Math.max(cur.actual,  r.cumulativeActualSpendEur),
      awarded: Math.max(cur.awarded, r.cumulativeAwardedSpendEur),
    });
  }
  let totalActual = 0, totalAwarded = 0, atRisk = 0;
  for (const { actual, awarded } of maxPerSup.values()) {
    totalActual  += actual;
    totalAwarded += awarded;
    if (awarded > 0 && actual / awarded >= 0.8) atRisk++;
  }
  const util = totalAwarded > 0 ? Math.round((totalActual / totalAwarded) * 100) : 0;
  const weeks = [...new Set(rows.map(r => r.contractWeek))].filter(Boolean).sort();
  // Clip adherence to a sensible range so single-row data errors (e.g. 1.5M%)
  // don't blow up the headline KPI. Anything beyond 0-200% is a data-quality
  // issue, not real signal — treat as 200 (still over-delivering).
  const clip = (v: number) => Math.max(0, Math.min(200, v));
  const adhVals = rows.map(r => clip(r.adherencePct)).filter(v => v > 0);
  const avgAdh = adhVals.length > 0
    ? adhVals.reduce((s, v) => s + v, 0) / adhVals.length
    : 0;
  return {
    totalActualSpendEur: Math.round(totalActual),
    totalAwardedSpendEur: Math.round(totalAwarded),
    budgetUtilizationPct: util,
    supplierCount: maxPerSup.size,
    contractStart: weeks[0] || '—',
    contractEnd:   weeks[weeks.length - 1] || '—',
    budgetRisk: util >= 90 ? 'High' : util >= 70 ? 'Medium' : 'Low',
    avgAdherencePct: Math.round(avgAdh),
    atRiskSuppliers: atRisk,
  };
}

export function computeSupplierSplit(rows: SpendRow[]): SupplierSplitEntry[] {
  const m = new Map<string, { actual: number; awarded: number }>();
  for (const r of rows) {
    const cur = m.get(r.supplier) ?? { actual: 0, awarded: 0 };
    m.set(r.supplier, {
      actual:  Math.max(cur.actual,  r.cumulativeActualSpendEur),
      awarded: Math.max(cur.awarded, r.cumulativeAwardedSpendEur),
    });
  }
  const total = [...m.values()].reduce((s, v) => s + v.actual, 0);
  return [...m.entries()]
    .map(([supplier, { actual, awarded }]) => ({
      supplier, actualEur: actual, awardedEur: awarded,
      pct: total > 0 ? Math.round((actual / total) * 100) : 0,
    }))
    .sort((a, b) => b.actualEur - a.actualEur);
}

// Snapshot data is single-week (latest export). We fan out to weekly time-series
// at query time using contractStart, contractEnd, and the cumulative spend
// figures captured at the snapshot week.
const SNAPSHOT_WEEK = '2026-W21';
function _weekToIndex(w: string): number {
  const m = /(\d{4})-W(\d{2})/.exec(w || '');
  return m ? Number(m[1]) * 53 + Number(m[2]) : 0;
}
function _indexToWeek(i: number): string {
  return `${Math.floor(i / 53)}-W${String(i % 53).padStart(2, '0')}`;
}

export function computeWeeklyChart(rows: SpendRow[]): WeeklySpendPoint[] {
  const wmap = new Map<string, { total: number; isForecast: boolean; [k: string]: number | boolean }>();
  const snapIdx = _weekToIndex(SNAPSHOT_WEEK);

  for (const r of rows) {
    const startIdx = _weekToIndex(r.contractStart);
    const endIdx   = _weekToIndex(r.contractEnd);
    if (startIdx === 0 || endIdx === 0 || endIdx <= startIdx) continue;

    const totalWeeks       = endIdx - startIdx + 1;
    const historicalWeeks  = Math.max(1, Math.min(snapIdx, endIdx) - startIdx + 1);
    const remainingWeeks   = Math.max(0, endIdx - snapIdx);

    // Spend the cumulative actual evenly across historical weeks
    const wkHistoricalSpend = r.cumulativeActualSpendEur / historicalWeeks;
    // Forecast remaining contract value evenly across remaining weeks
    const remainingValue    = Math.max(0, r.finalContractValueEur - r.cumulativeActualSpendEur);
    const wkForecastSpend   = remainingWeeks > 0 ? remainingValue / remainingWeeks : 0;

    for (let i = startIdx; i <= endIdx; i++) {
      const wk = _indexToWeek(i);
      const isForecast = i > snapIdx;
      const wkSpend = isForecast ? wkForecastSpend : wkHistoricalSpend;
      const entry = wmap.get(wk) ?? { total: 0, isForecast };
      entry.total = (entry.total as number) + wkSpend;
      entry.isForecast = entry.isForecast || isForecast;
      const supKey = supplierKey(r.supplier);
      entry[supKey] = ((entry[supKey] as number) || 0) + wkSpend;
      wmap.set(wk, entry);
    }
  }

  const weeks = [...wmap.keys()].sort();
  return weeks.map(w => {
    const e = wmap.get(w)!;
    return {
      week: w,
      weekLabel: w.replace('-W', ' W'),
      total: Math.round(e.total as number),
      isForecast: e.isForecast as boolean,
      ...Object.fromEntries(
        Object.entries(e)
          .filter(([k]) => k !== 'total' && k !== 'isForecast')
          .map(([k, v]) => [k, Math.round(v as number)]),
      ),
    } as WeeklySpendPoint;
  });
}

export function supplierKey(name: string): string {
  return name.toLowerCase().replace(/[^a-z0-9]/g, '_');
}

// ── Line-per-market chart (#1 quick win) ──────────────────────────────────────
// Same fan-out logic as computeWeeklyChart, but keyed by market instead of
// supplier — for the "line per market" chart mode.
export function computeWeeklyChartByMarket(rows: SpendRow[]): WeeklySpendPoint[] {
  const wmap = new Map<string, { total: number; isForecast: boolean; [k: string]: number | boolean }>();
  const snapIdx = _weekToIndex(SNAPSHOT_WEEK);

  for (const r of rows) {
    const startIdx = _weekToIndex(r.contractStart);
    const endIdx   = _weekToIndex(r.contractEnd);
    if (startIdx === 0 || endIdx === 0 || endIdx <= startIdx) continue;

    const historicalWeeks = Math.max(1, Math.min(snapIdx, endIdx) - startIdx + 1);
    const remainingWeeks  = Math.max(0, endIdx - snapIdx);
    const wkHistorical    = r.cumulativeActualSpendEur / historicalWeeks;
    const remainingValue  = Math.max(0, r.finalContractValueEur - r.cumulativeActualSpendEur);
    const wkForecast      = remainingWeeks > 0 ? remainingValue / remainingWeeks : 0;

    for (let i = startIdx; i <= endIdx; i++) {
      const wk = _indexToWeek(i);
      const isForecast = i > snapIdx;
      const wkSpend = isForecast ? wkForecast : wkHistorical;
      const entry = wmap.get(wk) ?? { total: 0, isForecast };
      entry.total = (entry.total as number) + wkSpend;
      entry.isForecast = entry.isForecast || isForecast;
      const mKey = r.market;
      entry[mKey] = ((entry[mKey] as number) || 0) + wkSpend;
      wmap.set(wk, entry);
    }
  }

  const weeks = [...wmap.keys()].sort();
  return weeks.map(w => {
    const e = wmap.get(w)!;
    return {
      week: w,
      weekLabel: w.replace('-W', ' W'),
      total: Math.round(e.total as number),
      isForecast: e.isForecast as boolean,
      ...Object.fromEntries(
        Object.entries(e)
          .filter(([k]) => k !== 'total' && k !== 'isForecast')
          .map(([k, v]) => [k, Math.round(v as number)]),
      ),
    } as WeeklySpendPoint;
  });
}

// ── Time aggregator (#3 quick win) ────────────────────────────────────────────
// Roll up week-level chart points into months or quarters.
export type TimeAggregation = 'week' | 'month' | 'quarter';

function _bucketLabel(week: string, agg: TimeAggregation): string {
  if (agg === 'week') return week;
  const m = /(\d{4})-W(\d{2})/.exec(week);
  if (!m) return week;
  const year = Number(m[1]);
  const wk   = Number(m[2]);
  // Approximate ISO week → month (each month ≈ 4.33 weeks)
  const monthIdx = Math.min(11, Math.floor((wk - 1) / 4.33));
  if (agg === 'month') {
    const monthNames = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return `${year} ${monthNames[monthIdx]}`;
  }
  // quarter
  const qIdx = Math.min(3, Math.floor(monthIdx / 3));
  return `${year} Q${qIdx + 1}`;
}

export function aggregateTimeSeries(points: WeeklySpendPoint[], agg: TimeAggregation): WeeklySpendPoint[] {
  if (agg === 'week') return points;
  const bucketMap = new Map<string, { total: number; isForecast: boolean; [k: string]: number | boolean }>();
  const bucketFirstWeek = new Map<string, string>();
  for (const p of points) {
    const bucket = _bucketLabel(p.week, agg);
    if (!bucketFirstWeek.has(bucket)) bucketFirstWeek.set(bucket, p.week);
    const entry = bucketMap.get(bucket) ?? { total: 0, isForecast: false };
    for (const [k, v] of Object.entries(p)) {
      if (k === 'week' || k === 'weekLabel') continue;
      if (k === 'isForecast') { entry.isForecast = entry.isForecast || (v as boolean); continue; }
      entry[k] = ((entry[k] as number) || 0) + (v as number);
    }
    bucketMap.set(bucket, entry);
  }
  return [...bucketMap.entries()]
    .sort((a, b) => (bucketFirstWeek.get(a[0]) || '').localeCompare(bucketFirstWeek.get(b[0]) || ''))
    .map(([bucket, entry]) => ({
      week: bucketFirstWeek.get(bucket) || bucket,
      weekLabel: bucket,
      total: Math.round(entry.total as number),
      isForecast: entry.isForecast as boolean,
      ...Object.fromEntries(
        Object.entries(entry)
          .filter(([k]) => k !== 'total' && k !== 'isForecast')
          .map(([k, v]) => [k, Math.round(v as number)]),
      ),
    } as WeeklySpendPoint));
}

// ── QoQ SKU count (#8 quick win) ──────────────────────────────────────────────
export interface SkuCountResult {
  current: number;
  previous: number;
  deltaPct: number;
  quarterLabel: string;
}
export function computeSkuQoQ(rows: SpendRow[]): SkuCountResult {
  // Snapshot quarter: derive from SNAPSHOT_WEEK. Previous = the quarter before.
  const m = /(\d{4})-W(\d{2})/.exec(SNAPSHOT_WEEK);
  if (!m) return { current: 0, previous: 0, deltaPct: 0, quarterLabel: '—' };
  const year = Number(m[1]);
  const wk   = Number(m[2]);
  const monthIdx = Math.min(11, Math.floor((wk - 1) / 4.33));
  const curQ    = Math.floor(monthIdx / 3) + 1;
  const prevQ   = curQ === 1 ? 4 : curQ - 1;
  const prevY   = curQ === 1 ? year - 1 : year;

  // A SKU "exists" in a quarter if its contract spans that quarter
  const qSpanWeeks = (qYear: number, qNum: number) => {
    const startMonth = (qNum - 1) * 3;
    const startWk = Math.max(1, Math.round(startMonth * 4.33) + 1);
    const endWk   = Math.min(53, Math.round((startMonth + 3) * 4.33));
    return { startWk: qYear * 53 + startWk, endWk: qYear * 53 + endWk };
  };
  const curSpan  = qSpanWeeks(year, curQ);
  const prevSpan = qSpanWeeks(prevY, prevQ);

  const skuActiveInRange = (r: SpendRow, startIdx: number, endIdx: number) => {
    const s = _weekToIndex(r.contractStart);
    const e = _weekToIndex(r.contractEnd);
    return s <= endIdx && e >= startIdx;
  };
  const curSkus  = new Set(rows.filter(r => skuActiveInRange(r, curSpan.startWk,  curSpan.endWk )).map(r => r.skuCode));
  const prevSkus = new Set(rows.filter(r => skuActiveInRange(r, prevSpan.startWk, prevSpan.endWk)).map(r => r.skuCode));
  const cur  = curSkus.size;
  const prev = prevSkus.size;
  const delta = prev > 0 ? Math.round(((cur - prev) / prev) * 100) : 0;
  return { current: cur, previous: prev, deltaPct: delta, quarterLabel: `${year} Q${curQ}` };
}

// Stable color palette — index matches sorted unique supplier list
export const SUPPLIER_PALETTE = [
  '#067A46', '#1565C0', '#E8820C', '#9C27B0', '#00838F',
  '#558B2F', '#C62828', '#37474F', '#6A1B9A', '#00695C',
  '#EF6C00', '#283593', '#AD1457', '#2E7D32', '#5D4037',
];

// Assign stable colors to all suppliers (sorted for determinism)
const SORTED_SUPPLIERS = [...new Set(ROWS.map(r => r.supplier))].sort();
export const SUPPLIER_COLOR: Record<string, string> = Object.fromEntries(
  SORTED_SUPPLIERS.map((s, i) => [s, SUPPLIER_PALETTE[i % SUPPLIER_PALETTE.length]]),
);
